1	import { useMemo, useState } from 'react';
2	import { Link, useSearchParams } from 'react-router-dom';
3	import { CompraParceladaForm } from '../components/CompraParceladaForm';
4	import { LimiteCartaoBarra } from '../components/LimiteCartaoBarra';
5	import { PagamentoFaturaForm } from '../components/PagamentoFaturaForm';
6	import { Alerta, Botao, CampoSelect, CampoTexto, Cartao, EstadoVazio, TituloPagina, Valor } from '../components/ui';
7	import {
8	  cartoesAtivos,
9	  cicloFatura,
10	  criarCompraParcelada,
11	  excluirPagamento,
12	  limiteCartao,
13	  mesFaturaAberta,
14	  registrarPagamento,
15	  resumoFatura,
16	  type SituacaoFatura,
17	} from '../domain/cartoes';
18	import { formatarData, hojeISO, mesValido, nomeMes, somarMeses } from '../domain/date';
19	import { formatarMoeda } from '../domain/money';
20	import { useEstado, useStore } from '../state/store';
21	
22	const ROTULO_SITUACAO: Record<SituacaoFatura, string> = { aberta: 'Aberta', fechada: 'Fechada', paga: 'Paga' };
23	const COR_SITUACAO: Record<SituacaoFatura, string> = {
24	  aberta: 'bg-sky-100 text-sky-900',
25	  fechada: 'bg-amber-100 text-amber-900',
26	  paga: 'bg-emerald-100 text-emerald-900',
27	};
28	
29	export function CartoesPage() {
30	  const store = useStore();
31	  const estado = useEstado();
32	  const [params, setParams] = useSearchParams();
33	  const [erro, setErro] = useState<string | null>(null);
34	  const hoje = hojeISO();
35	
36	  const cartoes = cartoesAtivos(estado.contas);
37	  const escolhido = cartoes.find((c) => c.id === params.get('cartao')) ?? cartoes[0];
38	  const mesParam = params.get('mes') ?? '';
39	  const mes = mesValido(mesParam) ? mesParam : escolhido?.cartao ? mesFaturaAberta(escolhido.cartao, hoje) : hoje.slice(0, 7);
40	
41	  const resumo = useMemo(() => (escolhido ? resumoFatura(estado, escolhido, mes, hoje) : null), [estado, escolhido, mes, hoje]);
42	  const limite = useMemo(() => (escolhido ? limiteCartao(estado, escolhido) : null), [estado, escolhido]);
43	  const categorias = new Map(estado.categorias.map((c) => [c.id, c.nome]));
44	  const pagamentos = estado.pagamentosFatura.filter((p) => escolhido && p.contaCartaoId === escolhido.id && p.mesFatura === mes);
45	  const contasOrigem = estado.contas.filter((c) => !c.arquivada && c.tipo !== 'cartao');
46	  const nomeConta = new Map(estado.contas.map((c) => [c.id, c.nome]));
47	
48	  const navegar = (parcial: Record<string, string>) => setParams({ ...(escolhido ? { cartao: escolhido.id } : {}), mes, ...parcial }, { replace: true });
49	
50	  if (!escolhido) {
51	    return (
52	      <div>
53	        <TituloPagina>Cartões</TituloPagina>
54	        <EstadoVazio titulo="Nenhum cartão de crédito" acao={<Link to="/contas" className="font-medium text-emerald-800 underline">Criar um cartão em Contas</Link>}>
55	          Cadastre uma conta do tipo cartão de crédito para acompanhar faturas, limite e parcelas.
56	        </EstadoVazio>
57	      </div>
58	    );
59	  }
60	
61	  return (
62	    <div>
63	      <TituloPagina>Cartões</TituloPagina>
64	      <div className="space-y-4">
65	        {erro ? <Alerta>{erro}</Alerta> : null}
66	        <Cartao>
67	          <div className="grid gap-3 sm:grid-cols-2">
68	            <CampoSelect label="Cartão" value={escolhido.id} onChange={(e) => setParams({ cartao: e.target.value })}>
69	              {cartoes.map((c) => (
70	                <option key={c.id} value={c.id}>
71	                  {c.nome}
72	                </option>
73	              ))}
74	            </CampoSelect>
75	          </div>
76	        </Cartao>
77	
78	        {!escolhido.cartao || !resumo || !limite ? (
79	          <EstadoVazio titulo="Cartão sem ciclo configurado" acao={<Link to="/contas" className="font-medium text-emerald-800 underline">Configurar em Contas</Link>}>
80	            Edite a conta "{escolhido.nome}" e informe o dia de fechamento, o dia de vencimento e o limite.
81	          </EstadoVazio>
82	        ) : (
83	          <>
84	            <Cartao titulo="Limite">
85	              <LimiteCartaoBarra limite={limite} total={escolhido.cartao.limite} />
86	            </Cartao>
87	
88	            <Cartao>
89	              <div className="flex flex-wrap items-end gap-3">
90	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, -1) })}>
91	                  Fatura anterior
92	                </Botao>
93	                <div className="w-44">
94	                  <CampoTexto label="Mês da fatura" type="month" value={mes} onChange={(e) => mesValido(e.target.value) && navegar({ mes: e.target.value })} />
95	                </div>
96	                <Botao variante="secundario" onClick={() => navegar({ mes: somarMeses(mes, 1) })}>
97	                  Próxima fatura
98	                </Botao>
99	              </div>
100	            </Cartao>
101	
102	            <Cartao
103	              titulo={`Fatura de ${nomeMes(mes)}`}
104	              acoes={
105	                <span className={`rounded-full px-2.5 py-0.5 text-xs font-semibold ${COR_SITUACAO[resumo.situacao]}`} data-testid="situacao">
106	                  {ROTULO_SITUACAO[resumo.situacao]}
107	                </span>
108	              }
109	            >
110	              <p className="mb-3 text-sm text-slate-600" data-testid="ciclo">
111	                Ciclo de {formatarData(cicloFatura(escolhido.cartao, mes).inicio)} a {formatarData(cicloFatura(escolhido.cartao, mes).fim)} · vence em{' '}
112	                <span data-testid="vencimento">{formatarData(resumo.vencimento)}</span>
113	              </p>
114	              <dl className="mb-3 grid gap-2 text-sm sm:grid-cols-3">
115	                <div>
116	                  <dt className="text-slate-600">Total da fatura</dt>
117	                  <dd className="text-lg font-bold" data-testid="fatura-total">{formatarMoeda(resumo.total)}</dd>
118	                </div>
119	                <div>
120	                  <dt className="text-slate-600">Pago</dt>
121	                  <dd data-testid="fatura-pago">{formatarMoeda(resumo.pago)}</dd>
122	                </div>
123	                <div>
124	                  <dt className="text-slate-600">Restante</dt>
125	                  <dd data-testid="fatura-restante">{formatarMoeda(resumo.restante)}</dd>
126	                </div>
127	              </dl>
128	              {resumo.transacoes.length === 0 ? (
129	                <p className="text-sm text-slate-600">Nenhuma compra neste ciclo.</p>
130	              ) : (
131	                <ul className="divide-y divide-slate-200" aria-label="Compras da fatura">
132	                  {resumo.transacoes.map((t) => (
133	                    <li key={t.id} className="flex flex-wrap items-center justify-between gap-2 py-2 text-sm">
134	                      <span className="min-w-0">
135	                        <span className="block truncate font-medium text-slate-900">{t.descricao || 'Sem descrição'}</span>
136	                        <span className="text-xs text-slate-600">
137	                          {formatarData(t.data)} · {categorias.get(t.categoriaId) ?? 'Sem categoria'}
138	                        </span>
139	                      </span>
140	                      <Valor centavos={t.tipo === 'despesa' ? -t.valor : t.valor} texto={formatarMoeda(t.tipo === 'despesa' ? -t.valor : t.valor)} />
141	                    </li>
142	                  ))}
143	                </ul>
144	              )}
145	            </Cartao>
146	
147	            <Cartao titulo="Pagamentos desta fatura">
148	              {pagamentos.length > 0 ? (
149	                <ul className="mb-4 divide-y divide-slate-200" aria-label="Pagamentos registrados">
150	                  {pagamentos.map((p) => (
151	                    <li key={p.id} className="flex flex-wrap items-center justify-between gap-2 py-2 text-sm">
152	                      <span>
153	                        {formatarData(p.data)} · de {nomeConta.get(p.contaOrigemId) ?? 'conta removida'} · {formatarMoeda(p.valor)}
154	                      </span>
155	                      <Botao
156	                        variante="secundario"
157	                        aria-label={`Excluir pagamento de ${formatarData(p.data)}`}
158	                        onClick={() => setErro(store.aplicar((s) => excluirPagamento(s, p.id)).ok ? null : 'Não foi possível excluir o pagamento.')}
159	                      >
160	                        Excluir
161	                      </Botao>
162	                    </li>
163	                  ))}
164	                </ul>
165	              ) : null}
166	              {resumo.restante > 0 ? (
167	                <PagamentoFaturaForm
168	                  key={`${escolhido.id}-${mes}-${resumo.restante}`}
169	                  contaCartaoId={escolhido.id}
170	                  mesFatura={mes}
171	                  restante={resumo.restante}
172	                  contasOrigem={contasOrigem}
173	                  onSalvar={(dados) => store.aplicar((s) => registrarPagamento(s, dados, hoje))}
174	                />
175	              ) : (
176	                <p className="text-sm text-slate-600">Não há valor a pagar nesta fatura.</p>
177	              )}
178	            </Cartao>
179	
180	            <Cartao titulo="Compra parcelada">
181	              <CompraParceladaForm contaId={escolhido.id} categorias={estado.categorias} onSalvar={(dados) => store.aplicar((s) => criarCompraParcelada(s, dados))} />
182	            </Cartao>
183	          </>
184	        )}
185	      </div>
186	    </div>
187	  );
188	}
189

1	export type Centavos = number;
2	/** Data no formato AAAA-MM-DD. */
3	export type DataISO = string;
4	/** Mês no formato AAAA-MM. */
5	export type Mes = string;
6	
7	export type TipoConta = 'corrente' | 'poupanca' | 'dinheiro' | 'cartao' | 'investimento';
8	export type TipoMovimento = 'receita' | 'despesa';
9	
10	/** Ciclo e limite de um cartão de crédito. Dias de 1 a 28 para valerem em todos os meses. */
11	export interface CartaoConfig {
12	  diaFechamento: number;
13	  diaVencimento: number;
14	  limite: Centavos;
15	}
16	
17	export interface Conta {
18	  id: string;
19	  nome: string;
20	  tipo: TipoConta;
21	  saldoInicial: Centavos;
22	  arquivada: boolean;
23	  criadaEm: number;
24	  /** Só para contas do tipo cartão. */
25	  cartao?: CartaoConfig;
26	}
27	
28	export interface Categoria {
29	  id: string;
30	  nome: string;
31	  tipo: TipoMovimento;
32	  arquivada: boolean;
33	}
34	
35	export interface Transacao {
36	  id: string;
37	  contaId: string;
38	  categoriaId: string;
39	  tipo: TipoMovimento;
40	  /** Sempre positivo; o sinal vem do tipo. */
41	  valor: Centavos;
42	  data: DataISO;
43	  descricao: string;
44	  criadaEm: number;
45	  importacaoId?: string;
46	  /** Etiquetas livres, normalizadas (minúsculas); ausente quando não há nenhuma. */
47	  tags?: string[];
48	  /** Presente em compras parceladas; as parcelas de uma compra compartilham o grupoId. */
49	  parcela?: { grupoId: string; numero: number; total: number };
50	}
51	
52	export interface Orcamento {
53	  categoriaId: string;
54	  mes: Mes;
55	  limite: Centavos;
56	}
57	
58	export interface Aporte {
59	  id: string;
60	  data: DataISO;
61	  /** Positivo para aporte, negativo para retirada. */
62	  valor: Centavos;
63	}
64	
65	export type StatusMeta = 'ativa' | 'concluida' | 'arquivada';
66	
67	export interface Meta {
68	  id: string;
69	  nome: string;
70	  valorAlvo: Centavos;
71	  prazo?: DataISO;
72	  aportes: Aporte[];
73	  status: StatusMeta;
74	  concluidaEm?: DataISO;
75	  criadaEm: number;
76	}
77	
78	/** Valor mensal fixo considerado na projeção; não gera transações. */
79	export interface Recorrencia {
80	  id: string;
81	  descricao: string;
82	  tipo: TipoMovimento;
83	  valor: Centavos;
84	  categoriaId: string;
85	  ativa: boolean;
86	}
87	
88	export type FormatoData = 'dd/mm/aaaa' | 'aaaa-mm-dd' | 'dd-mm-aaaa';
89	
90	export interface MapeamentoCsv {
91	  colData: number;
92	  colDescricao: number;
93	  /** Coluna única com sinal. */
94	  colValor: number | null;
95	  colCredito: number | null;
96	  colDebito: number | null;
97	  formatoData: FormatoData;
98	  temCabecalho: boolean;
99	}
100	
101	export interface Importacao {
102	  id: string;
103	  data: DataISO;
104	  contaId: string;
105	  transacaoIds: string[];
106	}
107	
108	/** Pagamento de fatura: movimenta dinheiro entre contas e não é receita nem despesa. */
109	export interface PagamentoFatura {
110	  id: string;
111	  contaCartaoId: string;
112	  /** Mês de fechamento da fatura (AAAA-MM). */
113	  mesFatura: Mes;
114	  valor: Centavos;
115	  data: DataISO;
116	  contaOrigemId: string;
117	}
118	
119	/** Lançamento agendado (conta a pagar ou a receber); só vira transação quando é pago. */
120	export interface Agendamento {
121	  id: string;
122	  descricao: string;
123	  tipo: TipoMovimento;
124	  valor: Centavos;
125	  vencimento: DataISO;
126	  categoriaId: string;
127	  contaId?: string;
128	  /** Presente nos lançamentos gerados por recorrência mensal. */
129	  serie?: { grupoId: string; numero: number; total: number };
130	  pagoEm?: DataISO;
131	  transacaoId?: string;
132	  criadoEm: number;
133	}
134	
135	export type ModoPadrao = 'contem' | 'comeca' | 'igual';
136	
137	/** Regra de categorização; a prioridade é a posição na lista `regras`. */
138	export interface RegraCategoria {
139	  id: string;
140	  padrao: string;
141	  modo: ModoPadrao;
142	  tipo: TipoMovimento;
143	  categoriaId: string;
144	  tags: string[];
145	  ativa: boolean;
146	}
147	
148	export type ClasseAtivo = 'renda-fixa' | 'acoes' | 'fundos' | 'cripto' | 'outros';
149	
150	export interface MovimentoAtivo {
151	  id: string;
152	  tipo: 'aporte' | 'resgate';
153	  data: DataISO;
154	  /** Sempre positivo; o sinal vem do tipo. */
155	  valor: Centavos;
156	}
157	
158	/** Valor de mercado anotado para um ativo numa data. */
159	export interface MarcacaoAtivo {
160	  id: string;
161	  data: DataISO;
162	  valor: Centavos;
163	}
164	
165	/** Ativo da carteira manual de investimentos; não gera transações nem mexe em saldos. */
166	export interface Ativo {
167	  id: string;
168	  nome: string;
169	  classe: ClasseAtivo;
170	  movimentos: MovimentoAtivo[];
171	  marcacoes: MarcacaoAtivo[];
172	  criadoEm: number;
173	}
174	
175	export type TipoDivida = 'devo' | 'emprestei';
176	export type SistemaAmortizacao = 'price' | 'sac';
177	
178	/** Pagamento de dívida; sem `parcela` é uma amortização extra. */
179	export interface PagamentoDivida {
180	  id: string;
181	  data: DataISO;
182	  valor: Centavos;
183	  parcela?: number;
184	}
185	
186	/** Dívida ou empréstimo concedido; `taxaBp` é a taxa mensal em centésimos de ponto percentual (199 = 1,99%). */
187	export interface Divida {
188	  id: string;
189	  nome: string;
190	  tipo: TipoDivida;
191	  principal: Centavos;
192	  taxaBp: number;
193	  parcelas: number;
194	  primeiraParcela: DataISO;
195	  sistema: SistemaAmortizacao;
196	  pagamentos: PagamentoDivida[];
197	  criadaEm: number;
198	}
199	
200	export interface AppState {
201	  schemaVersion: number;
202	  contas: Conta[];
203	  categorias: Categoria[];
204	  transacoes: Transacao[];
205	  orcamentos: Orcamento[];
206	  metas: Meta[];
207	  recorrencias: Recorrencia[];
208	  mapeamentosCsv: Record<string, MapeamentoCsv>;
209	  importacoes: Importacao[];
210	  pagamentosFatura: PagamentoFatura[];
211	  agenda: Agendamento[];
212	  regras: RegraCategoria[];
213	  investimentos: Ativo[];
214	  dividas: Divida[];
215	}
216	
217	export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };
218	
219	export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
220	export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });
221

1	import { useId, type ButtonHTMLAttributes, type HTMLAttributes, type InputHTMLAttributes, type ReactNode, type SelectHTMLAttributes } from 'react';
2	
3	const base =
4	  'w-full min-w-0 rounded-md border bg-white px-3 py-2 text-sm text-slate-900 focus:outline-none focus:ring-2 focus:ring-emerald-600';
5	
6	type VarianteBotao = 'primario' | 'secundario' | 'perigo' | 'link';
7	
8	const variantes: Record<VarianteBotao, string> = {
9	  primario: 'bg-emerald-700 text-white hover:bg-emerald-800',
10	  secundario: 'border border-slate-300 bg-white text-slate-800 hover:bg-slate-100',
11	  perigo: 'bg-red-700 text-white hover:bg-red-800',
12	  link: 'text-emerald-800 underline hover:text-emerald-950',
13	};
14	
15	export function Botao({
16	  variante = 'primario',
17	  className = '',
18	  type = 'button',
19	  ...props
20	}: ButtonHTMLAttributes<HTMLButtonElement> & { variante?: VarianteBotao }) {
21	  return (
22	    <button
23	      type={type}
24	      className={`inline-flex items-center justify-center rounded-md px-3 py-2 text-sm font-medium focus:outline-none focus:ring-2 focus:ring-emerald-600 focus:ring-offset-1 disabled:cursor-not-allowed disabled:opacity-50 ${variantes[variante]} ${className}`}
25	      {...props}
26	    />
27	  );
28	}
29	
30	interface CampoProps {
31	  label: string;
32	  erro?: string;
33	  dica?: string;
34	}
35	
36	export function CampoTexto({ label, erro, dica, className = '', ...props }: CampoProps & InputHTMLAttributes<HTMLInputElement>) {
37	  const id = useId();
38	  const idMsg = `${id}-msg`;
39	  return (
40	    <div className="min-w-0">
41	      <label htmlFor={id} className="mb-1 block text-sm font-medium text-slate-700">
42	        {label}
43	      </label>
44	      <input
45	        id={id}
46	        aria-invalid={erro ? true : undefined}
47	        aria-describedby={erro || dica ? idMsg : undefined}
48	        className={`${base} ${erro ? 'border-red-600' : 'border-slate-300'} ${className}`}
49	        {...props}
50	      />
51	      {erro ? (
52	        <p id={idMsg} role="alert" className="mt-1 text-sm text-red-700">
53	          {erro}
54	        </p>
55	      ) : dica ? (
56	        <p id={idMsg} className="mt-1 text-xs text-slate-600">
57	          {dica}
58	        </p>
59	      ) : null}
60	    </div>
61	  );
62	}
63	
64	export function CampoSelect({
65	  label,
66	  erro,
67	  dica,
68	  className = '',
69	  children,
70	  ...props
71	}: CampoProps & SelectHTMLAttributes<HTMLSelectElement> & { children: ReactNode }) {
72	  const id = useId();
73	  const idMsg = `${id}-msg`;
74	  return (
75	    <div className="min-w-0">
76	      <label htmlFor={id} className="mb-1 block text-sm font-medium text-slate-700">
77	        {label}
78	      </label>
79	      <select
80	        id={id}
81	        aria-invalid={erro ? true : undefined}
82	        aria-describedby={erro || dica ? idMsg : undefined}
83	        className={`${base} ${erro ? 'border-red-600' : 'border-slate-300'} ${className}`}
84	        {...props}
85	      >
86	        {children}
87	      </select>
88	      {erro ? (
89	        <p id={idMsg} role="alert" className="mt-1 text-sm text-red-700">
90	          {erro}
91	        </p>
92	      ) : dica ? (
93	        <p id={idMsg} className="mt-1 text-xs text-slate-600">
94	          {dica}
95	        </p>
96	      ) : null}
97	    </div>
98	  );
99	}
100	
101	export function Cartao({ titulo, children, acoes, className = '' }: { titulo?: string; children: ReactNode; acoes?: ReactNode; className?: string }) {
102	  return (
103	    <section className={`min-w-0 rounded-lg border border-slate-200 bg-white p-4 shadow-sm ${className}`}>
104	      {titulo || acoes ? (
105	        <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
106	          {titulo ? <h2 className="text-base font-semibold text-slate-900">{titulo}</h2> : <span />}
107	          {acoes}
108	        </div>
109	      ) : null}
110	      {children}
111	    </section>
112	  );
113	}
114	
115	export function TituloPagina({ children, acoes }: { children: ReactNode; acoes?: ReactNode }) {
116	  return (
117	    <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
118	      <h1 className="text-2xl font-bold text-slate-900">{children}</h1>
119	      {acoes}
120	    </div>
121	  );
122	}
123	
124	export function EstadoVazio({ titulo, children, acao }: { titulo: string; children?: ReactNode; acao?: ReactNode }) {
125	  return (
126	    <div className="rounded-lg border border-dashed border-slate-300 bg-white p-6 text-center">
127	      <p className="font-medium text-slate-900">{titulo}</p>
128	      {children ? <p className="mt-1 text-sm text-slate-600">{children}</p> : null}
129	      {acao ? <div className="mt-3 flex justify-center">{acao}</div> : null}
130	    </div>
