import { render } from '@testing-library/react';
import { MemoryRouter } from 'react-router-dom';
import { AppRoutes } from '../App';
import { CHAVE_ESTADO, estadoInicial, salvar } from '../storage/storage';
import { Store, StoreProvider } from '../state/store';
import type { AppState } from '../domain/types';
import { marcarTourConcluido } from '../lib/onboarding';

/** Renderiza o app numa rota, opcionalmente com um estado pré-salvo no localStorage. */
export function renderizarApp(rota = '/', estado?: AppState, opcoes: { tour?: boolean } = {}) {
  if (!opcoes.tour) marcarTourConcluido(localStorage);
  if (estado) salvar(estado, localStorage);
  const store = new Store(localStorage);
  const utils = render(
    <StoreProvider store={store}>
      <MemoryRouter initialEntries={[rota]}>
        <AppRoutes />
      </MemoryRouter>
    </StoreProvider>,
  );
  return { store, ...utils };
}

export function lerEstadoSalvo(): AppState {
  return JSON.parse(localStorage.getItem(CHAVE_ESTADO) ?? 'null') as AppState;
}

/** Estado inicial (com categorias padrão) sobrescrito por campos de teste. */
export function construirEstado(parcial: Partial<AppState> = {}): AppState {
  return { ...estadoInicial(), ...parcial };
}
let ultimoTempo = 0;

/** Timestamp estritamente crescente, para desempatar ordenações por criação. */
export function proximoTempo(): number {
  ultimoTempo = Math.max(Date.now(), ultimoTempo + 1);
  return ultimoTempo;
}

export function novoId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}
import type { Centavos } from './types';
import type { Comparativo, RelatorioAnual, RelatorioMensal, RelatorioPorCategoria } from './relatorios';

/** Decimal com vírgula e sem separador de milhar, como planilhas em pt-BR esperam. */
export function numeroCsv(centavos: Centavos): string {
  const abs = Math.abs(centavos);
  return `${centavos < 0 ? '-' : ''}${Math.floor(abs / 100)},${String(abs % 100).padStart(2, '0')}`;
}

export function percentualCsv(valor: number | null): string {
  return valor === null ? '' : String(valor).replace('.', ',');
}

/** Campos com `;`, aspas ou quebra de linha vão entre aspas, com as aspas internas dobradas. */
export function escaparCampoCsv(campo: string): string {
  return /[;"\r\n]/.test(campo) ? `"${campo.replace(/"/g, '""')}"` : campo;
}

/** Texto CSV com BOM UTF-8 (para o Excel reconhecer acentos) e separador `;`. */
export function gerarCsv(linhas: string[][]): string {
  return `﻿${linhas.map((l) => l.map(escaparCampoCsv).join(';')).join('\r\n')}\r\n`;
}

