            label="Grupo"
            value={grupo.id}
            onChange={(e) => {
              setParams({ grupo: e.target.value }, { replace: true });
              setEditando(null);
              setModo('ver');
            }}
          >
            {estado.gruposDivisao.map((g) => (
              <option key={g.id} value={g.id}>
                {g.nome}
              </option>
            ))}
          </CampoSelect>
