});

describe('critério 5: percentuais', () => {
  it('R$ 100,01 com 50/30/20 dá 50,01, 30,00 e 20,00', () => {
    const r = ratearDespesa(10001, 'percentual', [{ participanteId: 'a', peso: 5000 }, { participanteId: 'b', peso: 3000 }, { participanteId: 'c', peso: 2000 }]);
